begin;
create extension if not exists pgtap with schema extensions;
select plan(29);
select has_table('public','business_jobs','durable jobs exist');
select ok((select relrowsecurity from pg_class where oid='public.business_jobs'::regclass),'RLS enabled');
select ok(not has_table_privilege('authenticated','public.business_jobs','SELECT'),'browser read denied');
select ok(not has_table_privilege('service_role','public.business_jobs','UPDATE'),'service cannot bypass transition RPC');
set local role anon;
select throws_ok($$select public.claim_business_job(gen_random_uuid())$$,'42501',null,'anonymous claim denied');
reset role;
set local role service_role;
create temporary table fixture as select public.enqueue_business_job('a0000000-0000-0000-0000-000000000001','inbound_event','c0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000012','2040-01-01',2) id;
select is(public.enqueue_business_job('a0000000-0000-0000-0000-000000000001','inbound_event','c0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000012','2040-01-01',2),(select id from fixture),'same immutable input deduplicates');
select throws_ok($$select public.enqueue_business_job('a0000000-0000-0000-0000-000000000001','outbound_message','c0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000012','2040-01-01',2)$$,'22023','job_idempotency_conflict','changed input rejected');
select is((select count(*) from public.claim_business_job('b0000000-0000-4000-8000-000000000001',60,'2039-01-01')),0::bigint,'future not claimed');
create temporary table first_claim as select * from public.claim_business_job('b0000000-0000-4000-8000-000000000001',60,'2040-01-01');
select is((select attempts from first_claim),1,'first claim consumes attempt');
select is((select count(*) from public.claim_business_job('b0000000-0000-4000-8000-000000000002',60,'2040-01-01')),0::bigint,'second worker cannot claim live lease');
select ok(public.heartbeat_business_job(id,lease_owner,lease_token,60,'2040-01-01 00:00:30'),'live heartbeat extends lease') from first_claim;

create temporary table second_claim as select * from public.claim_business_job('b0000000-0000-4000-8000-000000000002',60,'2040-01-01 00:01:31');
select is((select attempts from second_claim),2,'crash reclaim consumes bounded attempt');
select isnt((select lease_token from first_claim),(select lease_token from second_claim),'reclaim rotates fencing token');
select ok(not public.finish_business_job(id,lease_owner,lease_token,null,'2040-01-01 00:01:32'),'stale completion fenced') from first_claim;
select ok(not public.heartbeat_business_job(id,lease_owner,lease_token,60,'2040-01-01 00:01:32'),'stale heartbeat fenced') from first_claim;
select throws_ok($$select public.finish_business_job(id,lease_owner,lease_token,'secret body','2040-01-01 00:01:32') from second_claim$$,'22023','invalid_job_outcome','raw error not accepted');
select ok(public.finish_business_job(id,lease_owner,lease_token,'handler_failed','2040-01-01 00:01:32'),'last failed attempt recorded') from second_claim;
select is((select status from public.business_jobs where id=(select id from fixture)),'dead','exhaustion dead letters');
savepoint business_mutation;
select public.enqueue_business_job('a0000000-0000-0000-0000-000000000001','inbound_event','c0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000013','2040-01-01',2);
rollback to savepoint business_mutation;
select is((select count(*) from public.business_jobs where dedup_key='e0000000-0000-4000-8000-000000000013'),0::bigint,'caller transaction rolls back enqueue');
select throws_ok($$select public.claim_business_job(gen_random_uuid(),301)$$,'22023','invalid_job_claim','lease length bounded');
select public.enqueue_business_job('a0000000-0000-0000-0000-000000000001','inbound_event','c0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000014','2042-01-01',3);
create temporary table retry_claim as select * from public.claim_business_job('b0000000-0000-4000-8000-000000000001',60,'2042-01-01');
select ok(public.finish_business_job(id,lease_owner,lease_token,'handler_failed','2042-01-01'),'failure schedules retry') from retry_claim;
select is((select available_at from public.business_jobs where id=(select id from retry_claim)),'2042-01-01 00:00:05+00'::timestamptz,'first backoff is five seconds');
select is((select count(*) from public.claim_business_job('b0000000-0000-4000-8000-000000000001',60,'2042-01-01 00:00:04')),0::bigint,'backoff enforced');
create temporary table success_claim as select * from public.claim_business_job('b0000000-0000-4000-8000-000000000001',60,'2042-01-01 00:00:05');
select ok(public.finish_business_job(id,lease_owner,lease_token,null,'2042-01-01 00:00:06'),'successful retry completes') from success_claim;
select is((select status from public.business_jobs where id=(select id from success_claim)),'succeeded','terminal success persisted');
select public.enqueue_business_job('a0000000-0000-0000-0000-000000000001','inbound_event','c0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000015','2043-01-01',1);
create temporary table crash_claim as select * from public.claim_business_job('b0000000-0000-4000-8000-000000000001',300,'2043-01-01');
select public.heartbeat_business_job(id,lease_owner,lease_token,300,'2043-01-01 00:04:59') from crash_claim;
select public.heartbeat_business_job(id,lease_owner,lease_token,300,'2043-01-01 00:09:58') from crash_claim;
select public.heartbeat_business_job(id,lease_owner,lease_token,300,'2043-01-01 00:14:57') from crash_claim;
select is((select lease_expires_at from public.business_jobs where id=(select id from crash_claim)),'2043-01-01 00:15:00+00'::timestamptz,'heartbeat capped at attempt deadline');
select ok(not public.finish_business_job(id,lease_owner,lease_token,null,'2043-01-01 00:15:00'),'expiry rejects completion even before reclaim') from crash_claim;
select is((select count(*) from public.claim_business_job('b0000000-0000-4000-8000-000000000002',60,'2043-01-01 00:15:01')),0::bigint,'exhausted crash never runs again');
select is((select status from public.business_jobs where id=(select id from crash_claim)),'dead','last-attempt crash dead letters');
select * from finish();
rollback;
